import {heroById,heroScaling} from './heroes.js';
const distance=(a,b)=>Math.hypot(a.x-b.x,a.y-b.y);
const home=h=>({x:h.homeX,y:h.homeY});
export function createHero(game,id,garden){const d=heroById(id),base=garden.mapDefinition.basePosition;return {id,definitionId:id,uid:++game.nextId,isHero:true,gardenId:garden.id,x:base.centerX+1.5,y:base.centerY,homeX:base.centerX+1.5,homeY:base.centerY,hp:d.hp,maxHp:d.hp,state:'idle',targetUid:null,target:null,attackTimer:0,abilityTimer:d.abilityCooldown,retargetTimer:0,passiveTimer:3,velocityX:0,velocityY:0,facing:1,downed:false,attackCue:0,abilityCue:0,hitCue:0,momentum:0,burst:0,burstTimer:0,metrics:{damage:0,kills:0,healing:0,downs:0},lastGardenId:garden.id}}
export function healHero(hero,amount){if(!hero||hero.downed||amount<=0)return 0;const n=Math.min(amount,hero.maxHp-hero.hp);hero.hp+=n;return n}
export function damageHero(game,hero,amount){if(!hero||hero.downed||amount<=0||game.state!=='playing')return 0;const reduced=hero.id==='brawler'&&hero.target&&distance(hero,hero.target)<1.5?.85:1,n=Math.min(hero.hp,amount*reduced);hero.hp-=n;hero.hitCue=.2;if(hero.hp<=0){hero.hp=0;hero.downed=true;hero.state='downed';hero.target=null;hero.targetUid=null;hero.velocityX=hero.velocityY=0;hero.burst=0;hero.metrics.downs++;game.heroMetrics.heroDowns++;game.events.emit('hero:downed',{hero,garden:game.gardens[hero.gardenId]})}return n}
export function reviveHero(game,hero){if(!hero.downed)return false;hero.downed=false;hero.hp=hero.maxHp*.6;hero.x=hero.homeX;hero.y=hero.homeY;hero.state='idle';hero.target=null;hero.targetUid=null;hero.attackTimer=0;hero.abilityTimer=heroById(hero.id).abilityCooldown;game.events.emit('hero:revived',{hero});return true}
function valid(h,z,g,d){return z&&z.hp>0&&g.zombies.includes(z)&&distance(home(h),z)<=d.leashRange+1&&distance(h,z)<=d.aggroRange+1}
function threat(z){return z.bossId?100:z.elite?80:z.id==='sporekeeper'?60:z.id==='brute'?40:z.id==='volatile'?30:0}
export function findHeroTarget(hero,garden){const d=heroById(hero.id),base=garden.mapDefinition.basePosition,candidates=garden.zombies.filter(z=>valid(hero,z,garden,d));const score=z=>d.targetStrategy==='base'?-Math.hypot(z.x-base.centerX,z.y-base.centerY):d.targetStrategy==='threat'?threat(z)*10-Math.hypot(z.x-base.centerX,z.y-base.centerY):d.targetStrategy==='cluster'?candidates.filter(q=>distance(z,q)<1.8).length*10-distance(hero,z):-distance(hero,z);return candidates.sort((a,b)=>score(b)-score(a))[0]||null}
export function updateHeroMovement(hero,garden,dt){const d=heroById(hero.id),target=hero.target;let destination=home(hero),movingState='returning';if(target){const range=distance(hero,target);hero.facing=target.x>=hero.x?1:-1;if(range>d.preferredRange+.15){const dx=hero.x-target.x,dy=hero.y-target.y;destination={x:target.x+dx/range*d.preferredRange,y:target.y+dy/range*d.preferredRange};movingState='moving'}else if(!d.minimumRange||range>=d.minimumRange){hero.velocityX=hero.velocityY=0;hero.state='attacking';return}}const leash=distance(home(hero),destination);if(leash>d.leashRange){destination={x:hero.homeX+(destination.x-hero.homeX)/leash*d.leashRange,y:hero.homeY+(destination.y-hero.homeY)/leash*d.leashRange}}const dx=destination.x-hero.x,dy=destination.y-hero.y,n=Math.hypot(dx,dy),step=Math.min(n,d.speed*(hero.momentum>0?1.25:1)*dt);hero.velocityX=n>.05?dx/n*step/dt:0;hero.velocityY=n>.05?dy/n*step/dt:0;if(n>.05){hero.x+=dx/n*step;hero.y+=dy/n*step;hero.facing=dx>=0?1:-1;hero.state=movingState}else hero.state=target?'attacking':'idle';hero.x=Math.max(.2,Math.min(garden.mapDefinition.cols-.2,hero.x));hero.y=Math.max(.2,Math.min(garden.mapDefinition.rows-.2,hero.y))}
function hit(game,hero,z,amount){if(z.hp<=0)return;const hp=z.hp;game.damage(z,amount);const dealt=Math.min(hp,Math.max(0,hp-z.hp));hero.metrics.damage+=dealt;game.heroMetrics.heroDamage+=dealt;if(z.hp<=0){hero.metrics.kills++;game.heroMetrics.heroKills++;if(hero.id==='vanguard')hero.momentum=3}}
function shot(game,hero,target,multiplier=1,pierce=false){const d=heroById(hero.id);game.shots.push({heroId:hero.id,hero,ownerUid:hero.uid,x:hero.x,y:hero.y,startX:hero.x,startY:hero.y,target,damage:d.attackDamage*heroScaling(game.wave)*multiplier,speed:10,color:d.visual.color,life:4,heroPierce:pierce});hero.attackCue=.25}
export function impactHeroShot(game,s){const g=game.simulationGarden,h=s.hero,z=s.target;if(z.hp<=0)return;hit(game,h,z,s.damage);if(h.id==='controller'){z.heroSlow=Math.max(z.heroSlow||0,2)}if(s.heroPierce){const dx=z.x-s.startX,dy=z.y-s.startY,len=Math.hypot(dx,dy)||1;for(const other of g.zombies){if(other===z||other.hp<=0)continue;const ox=other.x-s.startX,oy=other.y-s.startY,projection=(ox*dx+oy*dy)/len,perpendicular=Math.abs(ox*dy-oy*dx)/len;if(projection>0&&projection<len+4&&perpendicular<.65)hit(game,h,other,s.damage*.75)}game.effect(z.x,z.y,'#ddf6ff',1,.3,'PIERCE')}}
function heal(game,h,p,amount){const n=p.isHero?healHero(p,amount):game.healPlant(p,amount);h.metrics.healing+=n;game.heroMetrics.heroHealing+=n;return n}
export function triggerHeroAbility(game,h,garden=game.gardens[h?.gardenId]){if(!h||h.downed||!garden||garden.lost)return false;const d=heroById(h.id),target=h.target,scale=heroScaling(game.wave);if(h.id==='warden'){const plants=garden.plants.filter(p=>p.hp>0&&p.hp<p.maxHp&&Math.hypot(p.x+.5-h.x,p.y+.5-h.y)<3);if(!plants.length&&h.hp>=h.maxHp)return false;for(const p of plants)heal(game,h,p,p.maxHp*.18);heal(game,h,h,h.maxHp*.12)}else{if(!target||target.hp<=0||distance(h,target)>d.attackRange)return false;if(h.id==='vanguard'){h.burst=5;h.burstTimer=0}else if(h.id==='sentinel')shot(game,h,target,2,true);else if(h.id==='brawler'){for(const z of garden.zombies)if(z.hp>0&&distance(h,z)<2){hit(game,h,z,d.attackDamage*1.6*scale);const n=distance(h,z)||1,push=z.bossId?.3:.9;z.x=Math.max(.15,Math.min(garden.mapDefinition.cols-.15,z.x+(z.x-h.x)/n*push));z.y=Math.max(.15,Math.min(garden.mapDefinition.rows-.15,z.y+(z.y-h.y)/n*push));z.stun=Math.max(z.stun||0,z.bossId?.15:.5)}}else{garden.zones.push({type:'heroRoot',hero:h,x:target.x,y:target.y,r:2,t:5,tick:0,damage:6*scale})}}h.abilityTimer=d.abilityCooldown;h.abilityCue=.8;h.state='casting';game.effect(h.x,h.y,d.visual.color,1,.5,d.ability);game.events.emit('hero:ability',{hero:h,garden,ability:d.ability});return true}
export function updateHeroes(game,garden,dt){for(const h of garden.heroes){if(h.downed)continue;const d=heroById(h.id);const hp=d.hp*heroScaling(game.wave);if(hp!==h.maxHp){h.hp*=hp/h.maxHp;h.maxHp=hp}for(const key of ['attackTimer','abilityTimer','retargetTimer','passiveTimer','attackCue','abilityCue','hitCue','momentum','burstTimer'])h[key]=Math.max(0,h[key]-dt);if(h.retargetTimer<=0){h.retargetTimer=.25;const candidate=findHeroTarget(h,garden);if(!valid(h,h.target,garden,d)||(d.targetStrategy==='threat'&&candidate&&threat(candidate)>threat(h.target)+20))h.target=candidate;h.targetUid=h.target?.uid??null}if(h.target?.hp<=0){h.target=null;h.targetUid=null}updateHeroMovement(h,garden,dt);if(h.id==='warden'&&h.passiveTimer<=0){h.passiveTimer=3;const p=garden.plants.filter(p=>p.hp>0&&p.hp<p.maxHp&&Math.hypot(p.x+.5-h.x,p.y+.5-h.y)<3.5).sort((a,b)=>a.hp/a.maxHp-b.hp/b.maxHp)[0];if(p)heal(game,h,p,p.maxHp*.05)}if(h.abilityTimer<=0)triggerHeroAbility(game,h,garden);if(h.abilityCue>0)h.state='casting';const target=h.target;if(!target||distance(h,target)>d.attackRange)continue;if(h.burst>0&&h.burstTimer<=0){shot(game,h,target,1.1);h.burst--;h.burstTimer=.12}if(h.attackTimer<=0){h.attackTimer=d.attackInterval;if(h.id==='brawler'){hit(game,h,target,d.attackDamage*heroScaling(game.wave));h.attackCue=.3;game.effect(target.x,target.y,d.visual.color,.5,.2)}else shot(game,h,target)}}}
export function updateHeroRoot(game,zone,dt){zone.tick-=dt;for(const z of game.zombies)if(z.hp>0&&distance(z,zone)<=zone.r){z.heroRootSlow=.25;if(zone.tick<=0)hit(game,zone.hero,z,zone.damage)}if(zone.tick<=0)zone.tick=.5}
